  'sid': 'device.id.som_id',
  'sm': 'device.id.som_model',
  'snr': 'network.radio.snr_db',
  'temp': 'device.sensor.internal_temp_c',
  'tx': 'network.stats.bytes_sent',
  'uid': 'device.id.uid',
  'upt': 'device.runtime.uptime_s',
  'v': 'electrical.voltage_v'
};
var out = {};
var partialFailures = {};
var hasFailures = false;
var ignored = {
  'aa': true,
  'at': true,
  'ev': true,
  'ha': true
};
for (key : msg.keySet()) {
  if (key != 'schema' && key != 'ts' && key != 'deviceId' && key != 'deviceName') {
    if (ignored[key] == true) {

    }
    var canonical = mapping[key];
    if (canonical != null) {
      out[canonical] = msg[key];
    } else {
      partialFailures[key] = msg[key];
      hasFailures = true;
    }
  }
}
var result = out;
result['candidateType'] = 'device_state';
if (hasFailures) {
  result['partialFailures'] = partialFailures;
  return {msg: result, metadata: metadata, msgType: 'FAILURE'};
}
return {msg: result, metadata: metadata, msgType: msgType};

var routes = {
  'alarm': 'tier2.alarms.candidates',
  'device_state': 'tier2.state.candidates',
  'lifecycle': 'tier2.lifecycle.candidates',
  'ota': 'tier2.ota.candidates'
};
var candidateType = msg['candidateType'];
if (candidateType == null) { throw new Error('missing_candidate_type'); }
var topic = routes[candidateType];
if (topic == null) { throw new Error('unknown_candidate_type:' + candidateType); }
metadata['kafkaTopic'] = topic;
return {msg: msg, metadata: metadata, msgType: msgType};

var alarmMap = {
  '2001': 'modem.network.no_coverage',
  '2002': 'power.mains.lost',
  '2003': 'power.battery.low',
  '2004': 'power.modem.shutdown',
  '2005': 'modem.sim.not_detected',
  '2006': 'modem.network.registration_denied',
  '2007': 'uart.meter.no_response',
  '2008': 'backend.hes.connect_timeout',
  '2009': 'lifecycle.ota.failed',
  '2010': 'modem.network.registration_timeout',
  '2011': 'modem.sim.invalid',
  '2012': 'modem.rf.signal_low',
  '2013': 'modem.rf.signal_degraded',
  '2014': 'backend.hes.unreachable',
  '2015': 'backend.hes.rejection',
  '2016': 'power.thermal.warning',
  '2017': 'power.thermal.critical',
  '2018': 'storage.flash.wear_high',
  '2019': 'storage.flash.corruption',
  '2020': 'ota.download.failed',
  '2021': 'ota.apply.failed',
  '2022': 'ota.verify.failed',
  '2023': 'ota.rollback.failed',
  '2024': 'security.replay_detected',
  '2025': 'security.jamming_suspected',
  '2026': 'security.unknown_payload',
  '2046': 'lifecycle.pairing.mismatch',
  '2047': 'lifecycle.deployment.config_missing',
  '2048': 'lifecycle.commissioning.incomplete',
  '2049': 'lifecycle.som.lineage_missing',
  '2050': 'lifecycle.nic.build_incomplete'
};
var transitions = msg['ev'];
if (transitions == null) {
  return {msg: msg, metadata: metadata, msgType: 'IGNORE'};
}
var out = [];
for (t : transitions) {
  var code = '' + t['c'];
  var canonical = alarmMap[code];
  if (canonical != null) {
    var row = {'canonicalAlarm': canonical, 'sourceCode': code, 'state': t['s']};
    if (t['m'] != null) { row['metadata'] = t['m']; }
    out.push(row);
  }
}
if (out.size() == 0) {
  return {msg: msg, metadata: metadata, msgType: 'IGNORE'};
}
return {msg: {'candidateType': 'alarm', 'alarmTransitions': out}, metadata: metadata, msgType: 'Success'};

